function showCase(c){if(c.type==='allin'){location.href='case-'+c.id+'.html';return}currentCase=c;$('#modalTitle').textContent='Кейс «'+c.name+'»';$('#modalSub').textContent='Придуманный кейс · открытие за ✦ '+format(c.price)+' · выпадают только виртуальные предметы';let drops=c.drops.map(([id,w])=>{let p=P[id];return `<span class="drop-chip"><img src="${itemImage(p)}" alt="">${p.name}${p.duration?' · '+p.duration:''} <span>${dropPercent(c,w)}</span></span>`}).join('');$('#modalContent').innerHTML=`<div style="text-align:center"><img src="${A+('case-'+c.id+'.svg')}" alt="" style="height:155px"></div><p style="font-size:11px;color:#b1adbd;margin:4px 0">ВОЗМОЖНОЕ СОДЕРЖИМОЕ · ШАНСЫ</p><div class="drop-list">${drops}</div><p style="font-size:11px;color:#9895a9">✦ — игровые демо-монеты. Ориентиры цен на товары взяты из открытого каталога DashCase, цены придуманных кейсов условны. Реальных товаров и платежей нет.</p><div class="modal-buttons"><button class="btn btn-primary" id="confirmOpen" ${state.balance<c.price?'disabled':''}>Открыть за ✦ ${format(c.price)}</button><button class="btn btn-ghost" id="cancelOpen">Не сейчас</button></div>`;openModal()}
function roll(c){if(c.type==='allin'){location.href='case-'+c.id+'.html';return}if(busy||state.balance<c.price){notify('Недостаточно демо-монет');return}busy=true;state.balance-=c.price;let won=chooseDrop(c);let uid=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);state.inventory.push({id:won.id,uid});save();render();let pool=c.drops.map(([id])=>P[id]);let seq=Array.from({length:34},()=>pool[Math.floor(Math.random()*pool.length)]);seq[27]=won;$('#modalContent').innerHTML=`<div class="reel-viewport" id="reelViewport"><div class="reel-track" id="reelTrack">${seq.map(p=>`<div class="reel-cell"><img src="${itemImage(p)}" alt=""></div>`).join('')}</div></div><p class="modal-sub" style="text-align:center">Сундук открывается…</p><div class="result" id="rollResult">${itemMarkup(won)}<h3>${won.name}</h3><p>Предмет добавлен в инвентарь · виртуальная стоимость ✦ ${format(won.value)}</p><div class="modal-buttons" style="justify-content:center"><button class="btn btn-primary" id="againBtn">Ещё раз · ✦ ${format(c.price)}</button><button class="btn btn-ghost" id="doneBtn">В инвентарь →</button></div></div>`;$('#closeModal').disabled=true;requestAnimationFrame(()=>{requestAnimationFrame(()=>{let view=$('#reelViewport'),track=$('#reelTrack');if(!view||!track)return;let offset=27*98+45-view.clientWidth/2;track.style.transform=`translateX(-${offset}px)`})});setTimeout(()=>{let res=$('#rollResult');if(!res)return;res.style.display='block';let sub=$('#modalContent .modal-sub');if(sub)sub.remove();busy=false;$('#closeModal').disabled=false;let again=$('#againBtn');if(again)again.disabled=state.balance<c.price},3850)}
function bonus(){if(busy)return;let now=Date.now();if(now-(state.bonusAt||0)<86400000){notify('Бонус можно забрать раз в 24 часа');return}state.balance+=500;state.bonusAt=now;save();render();notify('+500 демо-монет на балансе!')}
function upgrade(){if(busy)return;let idx=state.inventory.findIndex(x=>x.uid===sourceUid),src=idx>=0&&P[state.inventory[idx].id],dst=P[targetId];if(!src||!dst||dst.value<=src.value)return;let chance=Math.min(85,src.value/dst.value*80);busy=true;$('#upgradeBtn').disabled=true;let sector=chance*3.6,angle=Math.random()*360,success=angle<sector;let pointer=$('#wheelPointer'),wheel=$('#chanceGauge');wheel.classList.remove('win','lose');pointer.style.transition='none';pointer.style.transform='rotate(0deg)';void pointer.offsetWidth;pointer.style.transition='transform 4s cubic-bezier(.12,.64,.12,1)';pointer.style.transform=`rotate(${360*6+angle}deg)`;$('#upgradeHint').textContent='Стрелка вращается… результат определится при остановке.';setTimeout(()=>{state.inventory.splice(idx,1);if(success)state.inventory.push({id:dst.id,uid:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10)});wheel.classList.add(success?'win':'lose');sourceUid=null;targetId=null;activeUpgradePreset=null;busy=false;save();render();wheel.style.setProperty('--chance',chance.toFixed(2).replace(/\.00$/,'')+'%');$('#chanceValue').textContent=chance.toFixed(2).replace(/\.00$/,'')+'%';$('#upgradeHint').textContent=success?'Стрелка на зелёном! Предмет получен.':'Стрелка не попала на зелёное. Предмет утрачен.';notify(success?'Успех! '+dst.name+' добавлен в инвентарь':'Не получилось. Предмет утрачен.');},4100)}
$('#caseGrid').addEventListener('click',e=>{let btn=e.target.closest('[data-case]');if(btn&&!busy&&document.body.dataset.case){let c=cases.find(x=>x.id===btn.dataset.case);if(c)showCase(c)}});$('.filters').addEventListener('click',e=>{let b=e.target.closest('[data-filter]');if(!b||busy)return;activeFilter=b.dataset.filter;document.querySelectorAll('.filter').forEach(f=>f.classList.toggle('active',f===b));renderCases()});$('#sellAllBtn').addEventListener('click',()=>{if(busy||!state.inventory.length)return;const count=state.inventory.length;const total=state.inventory.reduce((sum,x)=>sum+P[x.id].value,0);if(!confirm(`Продать все предметы (${count} шт.) за ✦ ${format(total)} демо-монет?`))return;state.balance+=total;state.inventory=[];sourceUid=null;targetId=null;save();render();notify(`Продано ${count} предметов за ✦ ${format(total)}`)});$('#inventoryGrid').addEventListener('click',e=>{let b=e.target.closest('[data-sell]');if(!b||busy)return;let idx=state.inventory.findIndex(x=>x.uid===b.dataset.sell);if(idx<0)return;let p=P[state.inventory[idx].id];if(!confirm(`Продать «${p.name}» за ${format(p.value)} демо-монет?`))return;state.inventory.splice(idx,1);state.balance+=p.value;if(sourceUid===b.dataset.sell){sourceUid=null;targetId=null}save();render();notify('Продано за ✦ '+format(p.value))});$('#sourcePicker').addEventListener('click',e=>{let b=e.target.closest('[data-source]');if(b&&!busy){sourceUid=b.dataset.source;targetId=null;activeUpgradePreset=null;$('#chanceGauge').classList.remove('win','lose');$('#wheelPointer').style.transition='none';$('#wheelPointer').style.transform='rotate(0deg)';renderUpgrade()}});$('#targetPicker').addEventListener('click',e=>{let b=e.target.closest('[data-target]');if(b&&!busy){targetId=b.dataset.target;activeUpgradePreset=null;$('#chanceGauge').classList.remove('win','lose');$('#wheelPointer').style.transition='none';$('#wheelPointer').style.transform='rotate(0deg)';renderUpgrade()}});$('#upgradePresets').addEventListener('click',e=>{let b=e.target.closest('[data-up-preset]');if(!b||busy)return;let owned=state.inventory.find(x=>x.uid===sourceUid),src=owned&&P[owned.id];if(!src)return;let choices=products.filter(x=>x.value>src.value);if(!choices.length)return;let v=Number(b.dataset.upPreset),wanted=v===30||v===75?src.value*80/v:src.value*v;let best=choices.reduce((a,x)=>Math.abs(x.value-wanted)<Math.abs(a.value-wanted)?x:a);targetId=best.id;activeUpgradePreset=b.dataset.upPreset;renderUpgrade();$('#targetSelection').scrollIntoView({block:'nearest',behavior:'smooth'})});$('#upgradeBtn').addEventListener('click',upgrade);$('#bonusBtn').addEventListener('click',bonus);$('#bonusBtnBottom').addEventListener('click',bonus);$('#topupBonus').addEventListener('click',bonus);$('#demoCreditForm').addEventListener('submit',e=>{e.preventDefault();if(busy)return;let amount=Number($('#demoCreditAmount').value);if(!Number.isSafeInteger(amount)||amount<1||amount>1000000){notify('Введите целое число от 1 до 1 000 000');return}state.balance+=amount;save();render();notify('Добавлено '+format(amount)+' демо-монет')});$('#resetBtn').addEventListener('click',()=>{if(busy)return;if(!confirm('Удалить весь демо-прогресс в этом браузере?'))return;state={balance:2500,inventory:[],bonusAt:0};sourceUid=null;targetId=null;save();render();notify('Демо-прогресс сброшен')});$('#closeModal').addEventListener('click',closeModal);$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#modalContent').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='confirmOpen'&&currentCase)roll(currentCase);if(b.id==='cancelOpen')closeModal();if(b.id==='againBtn'&&currentCase)showCase(currentCase);if(b.id==='doneBtn'){closeModal();location.href='profile.html'}});renderCases();render();if(!document.body.dataset.case){document.querySelectorAll('#caseGrid [data-case]').forEach(b=>{let a=document.createElement('a');a.href='case-'+b.dataset.case+'.html';a.className=b.className;a.textContent='Подробнее →';b.replaceWith(a)})}const pageCase=document.body.dataset.case; if(pageCase){let c=cases.find(x=>x.id===pageCase);if(c){$('#caseGrid').innerHTML=$('#caseGrid').querySelector(`[data-case="${c.id}"]`)?.closest('article')?.outerHTML||'';let detail=document.createElement('div');detail.className='case-detail';detail.innerHTML='<h3>Возможные дропы · шанс выпадения</h3><div class="case-detail-grid">'+c.drops.map(([id,w])=>{let p=P[id];return `<div class="detail-item"><img src="${itemImage(p)}" alt=""><div class="item-mini"><img src="${itemImage(p)}" alt=""><b>Мини-иконка</b></div><b>${p.name}</b><small>${p.duration||'Демо'} · ✦ ${format(p.value)} · ${dropPercent(c,w)}</small></div>`}).join('')+'</div><p style="color:#a9a6bd">Цены предметов — ориентиры каталога DashCase, цена кейса и вероятности придуманы для демо. Реальной выдачи нет.</p>';$('#cases').append(detail);}}

if(document.body.dataset.case){const c=cases.find(x=>x.id===document.body.dataset.case),section=$('#cases');if(c){const box=document.createElement('div');box.className='case-play';box.innerHTML=`<h3>${c.name}</h3><img class="play-art" src="${A+'case-'+c.id+'.svg'}" alt="Кейс ${c.name}"><p>${c.type==='allin'?'ALL IN · предметы выбранного сервера':'Выбери количество'} · один кейс ✦ ${format(c.price)}</p><div class="play-controls" role="group" aria-label="Количество кейсов">${(c.type==='allin'?[10,50,100]:[1,2,3,5,10]).map(n=>`<button class="play-count ${n===(c.minCount||1)?'active':''}" data-amount="${n}" aria-pressed="${n===(c.minCount||1)}">${n}</button>`).join('')}</div><button class="btn btn-primary play-submit" id="playOpen">Открыть</button><p class="play-status" id="playStatus" role="status" aria-live="polite">Результат появится здесь · все призы сохраняются в профиле.</p><div class="roll-stack" id="rollStack"></div><div class="batch-actions" id="batchActions"></div><div class="roll-wins" id="rollWins"></div>`;section.insertBefore(box,section.querySelector('.case-detail'));let amount=c.minCount||1;const go=$('#playOpen'),status=$('#playStatus');let batch=[];function updatePlay(){go.textContent=`Открыть ${amount} · ✦ ${format(c.price*amount)}`;go.disabled=busy||state.balance<c.price*amount;go.title=go.disabled&&!busy?'Недостаточно демо-монет':''}box.querySelector('.play-controls').addEventListener('click',e=>{let b=e.target.closest('[data-amount]');if(!b||busy)return;amount=Number(b.dataset.amount);box.querySelectorAll('[data-amount]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});updatePlay()});function updateBatch(){let owned=batch.filter(x=>state.inventory.some(i=>i.uid===x.uid));$('#batchActions').innerHTML=owned.length?`<button class="btn btn-ghost" id="sellBatch">Продать все из открытия (${owned.length}) · ✦ ${format(owned.reduce((a,x)=>a+P[x.id].value,0))}</button><a class="btn btn-ghost" href="profile.html">В профиль →</a>`:'';$('#rollWins').innerHTML=batch.map(x=>{let p=P[x.id],sold=!owned.some(y=>y.uid===x.uid);return `<article class="roll-win">${itemMarkup(p)}<strong>${p.name}</strong><small>✦ ${format(p.value)}</small><button data-win-sell="${x.uid}" ${sold?'disabled':''}>${sold?'Продано':'Продать сразу'}</button></article>`}).join('')}box.addEventListener('click',e=>{let sell=e.target.closest('[data-win-sell]');if(sell&&!busy){let idx=state.inventory.findIndex(i=>i.uid===sell.dataset.winSell);if(idx<0)return;state.balance+=P[state.inventory[idx].id].value;state.inventory.splice(idx,1);save();render();updateBatch();updatePlay();notify('Предмет продан')}if(e.target.id==='sellBatch'&&!busy){let ids=new Set(batch.map(x=>x.uid));let owned=state.inventory.filter(x=>ids.has(x.uid));if(!owned.length)return;let total=owned.reduce((a,x)=>a+P[x.id].value,0);if(!confirm(`Продать ${owned.length} предметов за ✦ ${format(total)}?`))return;state.balance+=total;state.inventory=state.inventory.filter(x=>!ids.has(x.uid));save();render();updateBatch();updatePlay();notify('Продано за ✦ '+format(total))}});go.addEventListener('click',()=>{if(busy)return;let count=amount,total=c.price*count;if(count<(c.minCount||1)||state.balance<total){notify('Недостаточно демо-монет');return}busy=true;state.balance-=total;batch=Array.from({length:count},()=>({id:chooseDrop(c).id,uid:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12)}));state.inventory.push(...batch);save();render();updatePlay();$('#batchActions').replaceChildren();$('#rollWins').replaceChildren();let stack=$('#rollStack');stack.replaceChildren();stack.classList.toggle('ten-split',count===10);status.textContent=`Открываем ${count} кейсов · барабаны вращаются…`;let pool=c.drops.map(([id])=>P[id]);let lanes=[];for(let j=0;j<Math.min(10,count);j++){if(j%5===0){let group=document.createElement('div');group.className='roll-group';group.innerHTML=`<h4>${count>5?`Сторона ${j===0?'I':'II'} · кейсы ${j+1}–${Math.min(j+5,count)}`:`Кейсы ${j+1}–${Math.min(j+5,count)}`}</h4>`;stack.append(group)}let lane=document.createElement('div');lane.className='roll-lane';let strip=document.createElement('div');strip.className='roll-strip';let seq=Array.from({length:26},()=>pool[Math.floor(Math.random()*pool.length)]);seq[20]=P[batch[j].id];strip.innerHTML=seq.map(p=>`<div class="roll-tile"><img src="${itemImage(p)}" alt=""><span>${p.name.split(' · ').at(-1).slice(0,12)}</span></div>`).join('');lane.append(strip);stack.lastElementChild.append(lane);lanes.push([lane,strip])}if(count>10){let note=document.createElement('p');note.className='roll-count-note';note.textContent=`Показаны 10 из ${count} барабанов · все ${count} результатов появятся ниже`;stack.append(note)}requestAnimationFrame(()=>requestAnimationFrame(()=>lanes.forEach(([lane,strip],j)=>{let w=strip.firstElementChild.getBoundingClientRect().width;strip.style.transition=`transform ${2.5+j*.2}s cubic-bezier(.12,.68,.14,1)`;strip.style.transform=`translateX(-${20*w+w/2-lane.clientWidth/2}px)`})));setTimeout(()=>{busy=false;render();updatePlay();status.textContent=`Открыто ${count} кейсов! Продай призы прямо здесь или оставь в профиле.`;updateBatch();notify('Открыто кейсов: '+count)},3700)});updatePlay();let old=section.querySelector('#caseGrid [data-case]');if(old)old.remove()}}
